use serde_json::Value;
use std::process::Command;

pub fn help(command: &[&str]) -> String {
    let temp = tempfile::tempdir().unwrap();
    let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
        .current_dir(temp.path())
        .env("DATABASE_URL", "invalid-url")
        .args(command)
        .arg("--help")
        .output()
        .unwrap();
    assert!(output.status.success());
    assert!(output.stderr.is_empty());
    assert_eq!(std::fs::read_dir(temp.path()).unwrap().count(), 0);
    String::from_utf8(output.stdout).unwrap()
}

pub fn schema(command: &[&str], label: &str) -> Value {
    let text = help(command);
    let tail = text
        .split_once(label)
        .expect("schema section exists")
        .1
        .trim_start();
    serde_json::Deserializer::from_str(tail)
        .into_iter::<Value>()
        .next()
        .unwrap()
        .unwrap()
}

pub fn validator(command: &[&str], label: &str) -> jsonschema::Validator {
    jsonschema::options()
        .should_validate_formats(true)
        .build(&schema(command, label))
        .unwrap()
}

pub fn validate(command: &[&str], label: &str, payload: &Value) {
    validator(command, label).validate(payload).unwrap();
}
use std::process::Command;

use clap::Parser;
use exposed::inbound::cli::ExposedCli;
use tempfile::TempDir;

const COMMANDS: &[&[&str]] = &[
    &["util", "latest"],
    &["util", "copy-latest-raw"],
    &["data", "declarations", "fetch"],
    &["data", "declarations", "clean"],
    &["data", "declarations", "resolve"],
    &["data", "declarations", "load"],
    &["data", "members", "fetch"],
    &["data", "members", "load"],
];

#[test]
fn commands_accept_named_config() {
    for command in COMMANDS {
        let args = ["exposed"]
            .into_iter()
            .chain(command.iter().copied())
            .chain(["--config", "config.yaml"]);
        assert!(ExposedCli::try_parse_from(args).is_ok(), "{command:?}");
    }
}

#[test]
fn commands_require_named_config() -> anyhow::Result<()> {
    let temporary = TempDir::new()?;
    for command in COMMANDS {
        for positional_config in [false, true] {
            let mut process = Command::new(env!("CARGO_BIN_EXE_exposed"));
            process.current_dir(temporary.path()).args(*command);
            if positional_config {
                process.arg("config.yaml");
            }
            let output = process.output()?;
            assert_eq!(output.status.code(), Some(2), "{command:?}");
            assert!(output.stdout.is_empty(), "{command:?}");
            let stderr = String::from_utf8_lossy(&output.stderr);
            if positional_config {
                assert!(
                    stderr.contains("unexpected argument 'config.yaml'"),
                    "{stderr}"
                );
            } else {
                assert!(stderr.contains("--config <CONFIG>"), "{stderr}");
                assert!(stderr.contains("required arguments"), "{stderr}");
            }
        }
    }
    assert_eq!(std::fs::read_dir(temporary.path())?.count(), 0);
    Ok(())
}

#[test]
fn utility_commands_are_rejected_under_data() {
    for command in ["latest", "copy-latest-raw"] {
        let error =
            ExposedCli::try_parse_from(["exposed", "data", command, "--config", "config.yaml"])
                .err()
                .expect("utilities belong under util");
        assert_eq!(error.kind(), clap::error::ErrorKind::InvalidSubcommand);
    }
}

#[test]
fn long_help_documents_yaml_without_reading_configuration() -> anyhow::Result<()> {
    let temporary = TempDir::new()?;
    for (command, expected, database_count) in [
        ("latest", vec!["data_dir (string, required)"], 0),
        ("copy-latest-raw", vec!["data_dir (string, required)"], 0),
        (
            "declarations",
            vec![
                "fetch:",
                "clean:",
                "resolve:",
                "load:",
                "batch_size (integer, required): API page size, from 1 to 255.",
                "candidate_budget (integer, optional, default 1000000)",
                "Must be positive.",
            ],
            2,
        ),
        (
            "members",
            vec!["fetch:", "load:", "batch_size (integer, required)"],
            1,
        ),
    ] {
        let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
            .current_dir(temporary.path())
            .env_remove("DATABASE_URL")
            .args(["data", command, "--config", "missing.yaml", "--help"])
            .output()?;
        assert!(output.status.success(), "{command}");
        assert!(output.stderr.is_empty(), "{command}");
        let help = String::from_utf8(output.stdout)?;
        let help = help.split_whitespace().collect::<Vec<_>>().join(" ");
        assert!(
            help.contains("Path to a YAML configuration file."),
            "{help}"
        );
        assert!(
            help.contains("Relative data_dir paths resolve against the current working directory."),
            "{help}"
        );
        for text in expected {
            assert!(help.contains(text), "missing {text:?} in {help}");
        }
        assert_eq!(
            help.matches("DATABASE_URL").count(),
            database_count,
            "{help}"
        );
        if command == "declarations" {
            let (_, stages) = help.split_once("fetch:").expect("fetch section exists");
            let (fetch, stages) = stages.split_once("clean:").expect("clean section exists");
            let (clean, stages) = stages
                .split_once("resolve:")
                .expect("resolve section exists");
            let (resolve, load) = stages.split_once("load:").expect("load section exists");
            assert!(fetch.contains("DATABASE_URL"), "{help}");
            assert!(!clean.contains("DATABASE_URL"), "{help}");
            assert!(!resolve.contains("DATABASE_URL"), "{help}");
            assert!(load.contains("DATABASE_URL"), "{help}");
        }
        if command == "members" {
            let (fetch, load) = help.split_once("load:").expect("load section exists");
            assert!(!fetch.contains("DATABASE_URL"), "{help}");
            assert!(load.contains("DATABASE_URL"), "{help}");
        }
        let short = Command::new(env!("CARGO_BIN_EXE_exposed"))
            .current_dir(temporary.path())
            .env_remove("DATABASE_URL")
            .args(["data", command, "-h"])
            .output()?;
        assert!(short.status.success());
        assert!(!String::from_utf8(short.stdout)?.contains("candidate_budget"));
    }
    assert_eq!(std::fs::read_dir(temporary.path())?.count(), 0);
    Ok(())
}

#[test]
fn documented_resolver_default_matches_yaml_parser() -> anyhow::Result<()> {
    use exposed::inbound::cli::config::DeclarationResolverConfig;

    let temporary = TempDir::new()?;
    let path = temporary.path().join("config.yaml");
    std::fs::write(&path, "data_dir: datasets\n")?;
    let config = DeclarationResolverConfig::try_from(&path)?;
    assert_eq!(config.candidate_budget, 1_000_000);
    assert_eq!(config.data_dir, std::path::PathBuf::from("datasets"));
    std::fs::write(&path, "candidate_budget: 1\n")?;
    assert!(DeclarationResolverConfig::try_from(&path).is_err());
    std::fs::write(&path, "data_dir: datasets\ncandidate_budget: 0\n")?;
    assert!(DeclarationResolverConfig::try_from(&path).is_err());
    Ok(())
}

