use std::path::PathBuf;

use clap::{Arg, ArgAction, ArgMatches, Args, Command, FromArgMatches};
use serde::Serialize;
use strum::IntoEnumIterator;

use super::config_help;
use crate::domain::models::entity_ingestion::{
    DeclarationIngestionStage, IngestionKey, MemberIngestionStage,
};

pub enum StageInput {
    Schema,
    Fetch {
        config: PathBuf,
        ingestion_key: Option<IngestionKey>,
    },
    Existing {
        config: PathBuf,
        ingestion_key: IngestionKey,
    },
}

/// A stage parsed with the inputs required to execute it or inspect its schema.
pub struct StageArgs<S> {
    pub stage: S,
    pub input: StageInput,
}

pub trait Stage: IntoEnumIterator + Serialize + Clone {
    fn config_help(&self) -> String;
    fn requires_key(&self) -> bool;
}

impl Stage for DeclarationIngestionStage {
    fn config_help(&self) -> String {
        config_help::declaration(self.clone())
    }

    fn requires_key(&self) -> bool {
        match self {
            Self::Fetch => false,
            Self::Clean | Self::Resolve | Self::Load => true,
        }
    }
}

impl Stage for MemberIngestionStage {
    fn config_help(&self) -> String {
        config_help::member(self.clone())
    }

    fn requires_key(&self) -> bool {
        match self {
            Self::Fetch => false,
            Self::Load => true,
        }
    }
}

fn name<S: Stage>(stage: &S) -> String {
    serde_json::to_value(stage)
        .expect("stage serializes")
        .as_str()
        .expect("stage is a string")
        .to_owned()
}

impl<S: Stage> Args for StageArgs<S> {
    fn augment_args(command: Command) -> Command {
        S::iter().fold(command.subcommand_required(true), |command, stage| {
            let stage_name = name(&stage);
            let example = format!(
                "Example:\n  exposed {{group}} {stage_name} --config config.yaml{}\n\nUse --schema to inspect success and failure JSON schemas without running the stage.",
                if stage.requires_key() { " --ingestion-key <UUID>" } else { "" }
            );
            command.subcommand(
                Command::new(stage_name)
                    .arg(Arg::new("config").long("config").value_name("CONFIG")
                        .value_parser(clap::value_parser!(PathBuf))
                        .required_unless_present("schema")
                        .help("Path to the stage YAML configuration")
                        .long_help(stage.config_help()))
                    .arg(Arg::new("ingestion_key").long("ingestion-key").value_name("INGESTION_KEY")
                        .value_parser(clap::value_parser!(IngestionKey))
                        .required_unless_present(if stage.requires_key() { "schema" } else { "ingestion_key" })
                        .help(if stage.requires_key() { "Existing ingestion run UUID" } else { "Capture run UUID. Defaults to a fresh UUID-v7" }))
                    .arg(Arg::new("schema").long("schema").action(ArgAction::SetTrue)
                        .help("Print response schemas without running the stage"))
                    .after_long_help(example),
            )
        })
    }

    fn augment_args_for_update(command: Command) -> Command {
        Self::augment_args(command)
    }
}

impl<S: Stage> FromArgMatches for StageArgs<S> {
    fn from_arg_matches(matches: &ArgMatches) -> Result<Self, clap::Error> {
        let (selected, args) = matches.subcommand().expect("stage is required");
        let stage = S::iter().find(|stage| name(stage) == selected).expect("known stage");
        let input = if args.get_flag("schema") {
            StageInput::Schema
        } else {
            let config = args.get_one::<PathBuf>("config").expect("config is required").clone();
            let ingestion_key = args.get_one::<IngestionKey>("ingestion_key").cloned();
            if stage.requires_key() {
                StageInput::Existing { config, ingestion_key: ingestion_key.expect("existing run key is required") }
            } else {
                StageInput::Fetch { config, ingestion_key }
            }
        };
        Ok(Self { stage, input })
    }

    fn update_from_arg_matches(&mut self, matches: &ArgMatches) -> Result<(), clap::Error> {
        *self = Self::from_arg_matches(matches)?;
        Ok(())
    }
}
