#[test]
fn every_yaml_config_error_names_selected_path() -> anyhow::Result<()> {
    let temporary = TempDir::new()?;
    let path = temporary.path().join("selected.yaml");
    for contents in [None, Some("data_dir: ["), Some("batch_size: wrong\\ndata_dir: datasets\\n")] {
        if let Some(contents) = contents { std::fs::write(&path, contents)?; }
        for command in COMMANDS {
            if contents == Some("batch_size: wrong\\ndata_dir: datasets\\n") && command.last() != Some(&"fetch") { continue; }
            let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
                .current_dir(temporary.path()).env_remove("DATABASE_URL").args(*command)
                .arg("--config").arg(&path).args(["--ingestion-key", "00000000-0000-4000-8000-000000000001"]).output()?;
            assert_eq!(output.status.code(), Some(1), "{command:?}");
            let payload: serde_json::Value = serde_json::from_slice(&output.stderr)?;
            assert!(payload["error"]["message"].as_str().unwrap().contains(path.to_str().unwrap()), "{payload}");
        }
    }
    Ok(())
}

#[test]
fn member_load_missing_artifact_does_not_create_raw_directory() -> anyhow::Result<()> {
    let temporary = TempDir::new()?;
    let config = temporary.path().join("config.yaml");
    std::fs::write(&config, "data_dir: data\\n")?;
    let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
        .current_dir(temporary.path()).env("DATABASE_URL", "postgresql://invalid")
        .args(["data", "members", "load", "--config"]).arg(config)
        .args(["--ingestion-key", "00000000-0000-4000-8000-000000000001"]).output()?;
    assert_eq!(output.status.code(), Some(1));
    assert!(String::from_utf8_lossy(&output.stderr).contains("raw/members.parquet"));
    assert!(!temporary.path().join("data").exists());
    Ok(())
}

