/// Command failures remain in the response until [`Response::write_to`] is called.
///
/// Failures include:
/// - Bad stage arg
/// - Bad config path
/// - Bad config shape
/// - Missing or non-Unicode `DATABASE_URL` for commands that use the database
/// - Service level failures
pub async fn run_cli(args: DataArgs) -> Response {
    match args.command {
        DataCommands::Declarations(args) => match args.input {
            stages::StageInput::Schema => {
                Response::schema(&response_help::declaration(&args.stage))
            }
            stages::StageInput::Fetch {
                config,
                ingestion_key,
            } => fetch_declarations(config, ingestion_key)
                .await
                .into_response(),
            stages::StageInput::Existing {
                config,
                ingestion_key,
            } => match args.stage {
                DeclarationIngestionStage::Fetch => unreachable!("fetch has its own input"),
                DeclarationIngestionStage::Clean => clean_declarations(config, ingestion_key)
                    .await
                    .into_response(),
                DeclarationIngestionStage::Resolve => resolve_declarations(config, ingestion_key)
                    .await
                    .into_response(),
                DeclarationIngestionStage::Load => load_declarations(config, ingestion_key)
                    .await
                    .into_response(),
            },
        },
        DataCommands::Members(args) => match args.input {
            stages::StageInput::Schema => Response::schema(&response_help::member(&args.stage)),
            stages::StageInput::Fetch {
                config,
                ingestion_key,
            } => members(args.stage, config, ingestion_key.unwrap_or_default())
                .await
                .into_response(),
            stages::StageInput::Existing {
                config,
                ingestion_key,
            } => members(args.stage, config, ingestion_key)
                .await
                .into_response(),
        },
    }
}

/// Entry point for ingestion utility commands.
pub async fn run_util(args: UtilArgs) -> Response {
    match args.command {
        UtilCommands::UuidV7 { schema: true } => {
            Response::schema(&response_help::inspection(uuid_v7))
        }
        UtilCommands::UuidV7 { schema: false } => uuid_v7().await.into_response(),
        UtilCommands::Latest(store) => {
            if store.schema {
                Response::schema(&response_help::inspection(latest))
            } else {
                latest(store.into_config()).await.into_response()
            }
        }
        UtilCommands::CopyLatestRaw {
            store,
            ingestion_key,
