#[cfg(unix)]
#[test]
fn schema_inspection_does_not_open_dotenv() -> anyhow::Result<()> {
    use std::{process::Stdio, time::{Duration, Instant}};

    let temporary = tempfile::tempdir()?;
    let fifo = temporary.path().join(".env");
    assert!(Command::new("mkfifo").arg(&fifo).status()?.success());
    for command in [
        vec!["data", "declarations", "fetch"],
        vec!["data", "declarations", "clean"],
        vec!["data", "declarations", "resolve"],
        vec!["data", "declarations", "load"],
        vec!["data", "members", "fetch"],
        vec!["data", "members", "load"],
        vec!["util", "latest"],
        vec!["util", "copy-latest-raw"],
        vec!["util", "uuid-v7"],
    ] {
        let mut child = Command::new(env!("CARGO_BIN_EXE_exposed"))
            .current_dir(temporary.path()).env_clear().args(&command).arg("--schema")
            .stdout(Stdio::piped()).stderr(Stdio::piped()).spawn()?;
        let deadline = Instant::now() + Duration::from_secs(3);
        while child.try_wait()?.is_none() {
            if Instant::now() >= deadline {
                child.kill()?;
                child.wait()?;
                panic!("{command:?} blocked while opening .env");
            }
            std::thread::sleep(Duration::from_millis(10));
        }
        let output = child.wait_with_output()?;
        assert!(output.status.success(), "{command:?}");
        assert!(output.stderr.is_empty());
        let schema: serde_json::Value = serde_json::from_slice(&output.stdout)?;
        assert!(schema["success"].is_object());
        assert!(schema["failure"].is_object());
    }
    Ok(())
}
